'use client'

import { useEffect, useState } from 'react'
import { supabase } from '@/lib/supabase'

export default function Home() {
  const [connected, setConnected] = useState(false)
  const [loading, setLoading] = useState(true)
  
  useEffect(() => {
    // Test connection
    supabase
      .from('matches')
      .select('count')
      .then(() => {
        setConnected(true)
        setLoading(false)
      })
      .catch(() => {
        setLoading(false)
      })
  }, [])

  return (
    <div className="flex min-h-screen items-center justify-center bg-gradient-to-br from-blue-50 to-green-50">
      <div className="text-center p-8 bg-white rounded-2xl shadow-xl">
        <h1 className="text-5xl font-bold mb-6 text-gray-800">
          🏏 Cricket Predictions
        </h1>
        <div className="text-2xl">
          {loading && <p className="text-gray-500">⏳ Connecting...</p>}
          {!loading && connected && (
            <p className="text-green-600 font-semibold">
              ✅ Connected to Supabase!
            </p>
          )}
          {!loading && !connected && (
            <p className="text-red-600">❌ Connection Failed</p>
          )}
        </div>
        {!loading && connected && (
          <p className="text-gray-600 mt-4">
            Ready to build your cricket prediction game! 🚀
          </p>
        )}
      </div>
    </div>
  )
}
